CREATE TABLE en1998_document (id INTEGER PRIMARY KEY CHECK(id=1),annex TEXT NOT NULL);
CREATE TABLE en1998_site (id INTEGER PRIMARY KEY CHECK(id=1),document_id INTEGER NOT NULL REFERENCES en1998_document(id) CHECK(document_id=1),seismic_zone TEXT NOT NULL CHECK(seismic_zone IN ('zone0','zone1','zone2','zone3')),a_gr REAL,de_ground_combo TEXT NOT NULL CHECK(de_ground_combo IN ('A-R','B-R','C-R','B-T','C-T','C-S')),en_ground_type TEXT NOT NULL,en_spectrum_type TEXT NOT NULL,importance_class TEXT NOT NULL,a_gr_ieee754_bits INTEGER NOT NULL,a_gr_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_building (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1998_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,name TEXT NOT NULL,plan_width_m REAL,plan_length_m REAL,plan_regular INTEGER NOT NULL CHECK(plan_regular IN (0,1)),elevation_regular INTEGER NOT NULL CHECK(elevation_regular IN (0,1)),t1_method TEXT NOT NULL,t1_given_s REAL,ct REAL,drift_limit_class TEXT NOT NULL,nu REAL,multiple_resisting_systems INTEGER NOT NULL CHECK(multiple_resisting_systems IN (0,1)),claims_simple_masonry INTEGER NOT NULL CHECK(claims_simple_masonry IN (0,1)),masonry_wall_area_ratio REAL,accidental_eccentricity_ratio REAL,plan_width_m_ieee754_bits INTEGER NOT NULL,plan_width_m_ieee754_class TEXT NOT NULL,plan_length_m_ieee754_bits INTEGER NOT NULL,plan_length_m_ieee754_class TEXT NOT NULL,t1_given_s_ieee754_bits INTEGER NOT NULL,t1_given_s_ieee754_class TEXT NOT NULL,ct_ieee754_bits INTEGER NOT NULL,ct_ieee754_class TEXT NOT NULL,nu_ieee754_bits INTEGER NOT NULL,nu_ieee754_class TEXT NOT NULL,masonry_wall_area_ratio_ieee754_bits INTEGER NOT NULL,masonry_wall_area_ratio_ieee754_class TEXT NOT NULL,accidental_eccentricity_ratio_ieee754_bits INTEGER NOT NULL,accidental_eccentricity_ratio_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_system (id INTEGER PRIMARY KEY,building_id INTEGER NOT NULL REFERENCES en1998_building(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,direction TEXT NOT NULL,system_type TEXT NOT NULL,material TEXT NOT NULL,ductility_class TEXT NOT NULL,q0 REAL,alpha_u_over_alpha_1 REAL,k_w REAL,base_shear_resistance_n REAL,q0_ieee754_bits INTEGER NOT NULL,q0_ieee754_class TEXT NOT NULL,alpha_u_over_alpha_1_ieee754_bits INTEGER NOT NULL,alpha_u_over_alpha_1_ieee754_class TEXT NOT NULL,k_w_ieee754_bits INTEGER NOT NULL,k_w_ieee754_class TEXT NOT NULL,base_shear_resistance_n_ieee754_bits INTEGER NOT NULL,base_shear_resistance_n_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_storey (id INTEGER PRIMARY KEY,building_id INTEGER NOT NULL REFERENCES en1998_building(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,height_m REAL,permanent_gk_n REAL,correlated_occupancy INTEGER NOT NULL CHECK(correlated_occupancy IN (0,1)),stiffness_x REAL,stiffness_y REAL,centre_of_mass_x_m REAL,centre_of_mass_y_m REAL,centre_of_stiffness_x_m REAL,centre_of_stiffness_y_m REAL,drift_x_m REAL,drift_y_m REAL,shear_resistance_n REAL,height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,permanent_gk_n_ieee754_bits INTEGER NOT NULL,permanent_gk_n_ieee754_class TEXT NOT NULL,stiffness_x_ieee754_bits INTEGER NOT NULL,stiffness_x_ieee754_class TEXT NOT NULL,stiffness_y_ieee754_bits INTEGER NOT NULL,stiffness_y_ieee754_class TEXT NOT NULL,centre_of_mass_x_m_ieee754_bits INTEGER NOT NULL,centre_of_mass_x_m_ieee754_class TEXT NOT NULL,centre_of_mass_y_m_ieee754_bits INTEGER NOT NULL,centre_of_mass_y_m_ieee754_class TEXT NOT NULL,centre_of_stiffness_x_m_ieee754_bits INTEGER NOT NULL,centre_of_stiffness_x_m_ieee754_class TEXT NOT NULL,centre_of_stiffness_y_m_ieee754_bits INTEGER NOT NULL,centre_of_stiffness_y_m_ieee754_class TEXT NOT NULL,drift_x_m_ieee754_bits INTEGER NOT NULL,drift_x_m_ieee754_class TEXT NOT NULL,drift_y_m_ieee754_bits INTEGER NOT NULL,drift_y_m_ieee754_class TEXT NOT NULL,shear_resistance_n_ieee754_bits INTEGER NOT NULL,shear_resistance_n_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_storey_variable (id INTEGER PRIMARY KEY,storey_id INTEGER NOT NULL REFERENCES en1998_storey(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,category TEXT NOT NULL,qk_n REAL,qk_n_ieee754_bits INTEGER NOT NULL,qk_n_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_member (id INTEGER PRIMARY KEY,building_id INTEGER NOT NULL REFERENCES en1998_building(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,material TEXT NOT NULL,role TEXT NOT NULL,detailing_compatible_with_q INTEGER NOT NULL CHECK(detailing_compatible_with_q IN (0,1)),min_dimension_m REAL,rho REAL,rho_prime REAL,omega_wd REAL,steel_section_class INTEGER NOT NULL CHECK(steel_section_class BETWEEN 0 AND 255),min_dimension_m_ieee754_bits INTEGER NOT NULL,min_dimension_m_ieee754_class TEXT NOT NULL,rho_ieee754_bits INTEGER NOT NULL,rho_ieee754_class TEXT NOT NULL,rho_prime_ieee754_bits INTEGER NOT NULL,rho_prime_ieee754_class TEXT NOT NULL,omega_wd_ieee754_bits INTEGER NOT NULL,omega_wd_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_bridge (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1998_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,period_ratio REAL,fundamental_period_s REAL,v_rd_n REAL,bearing_d_rd_m REAL,permanent_gk_n REAL,correlated_occupancy INTEGER NOT NULL CHECK(correlated_occupancy IN (0,1)),period_ratio_ieee754_bits INTEGER NOT NULL,period_ratio_ieee754_class TEXT NOT NULL,fundamental_period_s_ieee754_bits INTEGER NOT NULL,fundamental_period_s_ieee754_class TEXT NOT NULL,v_rd_n_ieee754_bits INTEGER NOT NULL,v_rd_n_ieee754_class TEXT NOT NULL,bearing_d_rd_m_ieee754_bits INTEGER NOT NULL,bearing_d_rd_m_ieee754_class TEXT NOT NULL,permanent_gk_n_ieee754_bits INTEGER NOT NULL,permanent_gk_n_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_bridge_variable (id INTEGER PRIMARY KEY,bridge_id INTEGER NOT NULL REFERENCES en1998_bridge(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,category TEXT NOT NULL,qk_n REAL,qk_n_ieee754_bits INTEGER NOT NULL,qk_n_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_assessment (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1998_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,knowledge_level TEXT NOT NULL,limit_state TEXT NOT NULL,building_logical_id TEXT NOT NULL,r_k_n REAL,gamma_el REAL,r_k_n_ieee754_bits INTEGER NOT NULL,r_k_n_ieee754_class TEXT NOT NULL,gamma_el_ieee754_bits INTEGER NOT NULL,gamma_el_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_silo (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1998_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,height_m REAL,radius_m REAL,permanent_gk_n REAL,content_qk_n REAL,content_category TEXT NOT NULL,filling_ratio REAL,n_rd_n REAL,v_rd_n REAL,q_nominal REAL,height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,radius_m_ieee754_bits INTEGER NOT NULL,radius_m_ieee754_class TEXT NOT NULL,permanent_gk_n_ieee754_bits INTEGER NOT NULL,permanent_gk_n_ieee754_class TEXT NOT NULL,content_qk_n_ieee754_bits INTEGER NOT NULL,content_qk_n_ieee754_class TEXT NOT NULL,filling_ratio_ieee754_bits INTEGER NOT NULL,filling_ratio_ieee754_class TEXT NOT NULL,n_rd_n_ieee754_bits INTEGER NOT NULL,n_rd_n_ieee754_class TEXT NOT NULL,v_rd_n_ieee754_bits INTEGER NOT NULL,v_rd_n_ieee754_class TEXT NOT NULL,q_nominal_ieee754_bits INTEGER NOT NULL,q_nominal_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_tank (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1998_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,height_m REAL,radius_m REAL,permanent_gk_n REAL,content_qk_n REAL,content_category TEXT NOT NULL,filling_ratio REAL,v_rd_n REAL,height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,radius_m_ieee754_bits INTEGER NOT NULL,radius_m_ieee754_class TEXT NOT NULL,permanent_gk_n_ieee754_bits INTEGER NOT NULL,permanent_gk_n_ieee754_class TEXT NOT NULL,content_qk_n_ieee754_bits INTEGER NOT NULL,content_qk_n_ieee754_class TEXT NOT NULL,filling_ratio_ieee754_bits INTEGER NOT NULL,filling_ratio_ieee754_class TEXT NOT NULL,v_rd_n_ieee754_bits INTEGER NOT NULL,v_rd_n_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_foundation (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1998_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,building_logical_id TEXT NOT NULL,area_m2 REAL,p_rd_pa REAL,h_rd_n REAL,k_foundation REAL,k_soil REAL,area_m2_ieee754_bits INTEGER NOT NULL,area_m2_ieee754_class TEXT NOT NULL,p_rd_pa_ieee754_bits INTEGER NOT NULL,p_rd_pa_ieee754_class TEXT NOT NULL,h_rd_n_ieee754_bits INTEGER NOT NULL,h_rd_n_ieee754_class TEXT NOT NULL,k_foundation_ieee754_bits INTEGER NOT NULL,k_foundation_ieee754_class TEXT NOT NULL,k_soil_ieee754_bits INTEGER NOT NULL,k_soil_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_retaining_wall (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1998_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,height_m REAL,phi_deg REAL,soil_gamma REAL,r REAL,h_rd_n_per_m REAL,height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,phi_deg_ieee754_bits INTEGER NOT NULL,phi_deg_ieee754_class TEXT NOT NULL,soil_gamma_ieee754_bits INTEGER NOT NULL,soil_gamma_ieee754_class TEXT NOT NULL,r_ieee754_bits INTEGER NOT NULL,r_ieee754_class TEXT NOT NULL,h_rd_n_per_m_ieee754_bits INTEGER NOT NULL,h_rd_n_per_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_tower (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1998_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,height_m REAL,m_rd_nm REAL,is_chimney INTEGER NOT NULL CHECK(is_chimney IN (0,1)),q_nominal REAL,permanent_gk_n REAL,correlated_occupancy INTEGER NOT NULL CHECK(correlated_occupancy IN (0,1)),height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,m_rd_nm_ieee754_bits INTEGER NOT NULL,m_rd_nm_ieee754_class TEXT NOT NULL,q_nominal_ieee754_bits INTEGER NOT NULL,q_nominal_ieee754_class TEXT NOT NULL,permanent_gk_n_ieee754_bits INTEGER NOT NULL,permanent_gk_n_ieee754_class TEXT NOT NULL);
CREATE TABLE en1998_tower_variable (id INTEGER PRIMARY KEY,tower_id INTEGER NOT NULL REFERENCES en1998_tower(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,category TEXT NOT NULL,qk_n REAL,qk_n_ieee754_bits INTEGER NOT NULL,qk_n_ieee754_class TEXT NOT NULL);
